  // ---- Theme toggle (Day / Night) ----
  var themeBtn = document.getElementById('themeBtn');
  var themeLabel = themeBtn.querySelector('.theme-label');
  var LABEL_OFFER_NIGHT = '<span class="t-en">Night Mode</span><span class="sep">·</span><span class="t-zh" lang="zh">夜晚模式</span>';
  var LABEL_OFFER_DAY   = '<span class="t-en">Day Mode</span><span class="sep">·</span><span class="t-zh" lang="zh">白天模式</span>';
  function applyTheme(theme, persist){
    var night = (theme === 'night');
    document.body.classList.toggle('night', night);
    themeLabel.innerHTML = night ? LABEL_OFFER_DAY : LABEL_OFFER_NIGHT;
    themeBtn.setAttribute('aria-label', night
      ? 'Switch to day mode · 切换到白天模式'
      : 'Switch to night mode · 切换到夜晚模式');
    if(persist){
      try{ localStorage.setItem('sky-theme', theme); }catch(err){}
    }
  }
  themeBtn.addEventListener('click', function(){
    applyTheme(document.body.classList.contains('night') ? 'day' : 'night', true);
  });
  var savedTheme = null;
  try{ savedTheme = localStorage.getItem('sky-theme'); }catch(err){}
  if(savedTheme === 'night' || savedTheme === 'day'){ applyTheme(savedTheme, false); }

  // ---- Fade cards in on scroll ----
