missing = []
for fname in ('sky.md', 'sky2.md'):
    for i, raw in enumerate(open(fname, encoding='utf-8').read().splitlines(), 1):
        line = raw.strip()
        if not line or line == '---':
            continue
        if line.startswith('#'):
            # heading: allow extra # levels or " / " bilingual suffix
            text = line.lstrip('#').strip()
            base = text.split(' / ')[0].strip()
            pat = re.escape(base).replace(r'\ ', r'(\\s|/\\s)?')
            ok = any(base in m and m.lstrip('#').split(' / ')[0].strip() == base
                     for m in merged_lines if m.startswith('#'))
            if not ok:
                missing.append((fname, i, line))
        else:
            if line not in merged_lines:
                missing.append((fname, i, line))

if missing:
    print("MISSING LINES:")
    for f, i, l in missing: print(f"  {f}:{i}: {l[:80]}")
else:
    print("All content lines from sky.md and sky2.md present in sky_bilingual.md")

# structure check
heads = [l for l in merged.splitlines() if l.startswith('##')]
