import kotlin.math.roundToInt

private val STANDARD_SHUTTER_DENOMINATORS = intArrayOf(
    8, 15, 30, 60, 125, 250, 500, 1000, 2000, 4000, 8000, 15000, 30000
)

fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "--"
    val seconds = exposureTimeNs / 1_000_000_000.0
    if (seconds >= 0.1) {
        val whole = seconds.roundToInt()
        return if (whole >= 1 && kotlin.math.abs(seconds - whole) < 0.05) {
            "${whole}s"
        } else {
            String.format("%.2f", seconds).trimEnd('0').trimEnd('.') + "s"
        }
    }
    val reciprocal = 1.0 / seconds
    val nearest = STANDARD_SHUTTER_DENOMINATORS.minByOrNull { kotlin.math.abs(it - reciprocal) / it }!!
    return "1/${nearest}s"
}

fun main() {
    val cases = longArrayOf(
        0L,
        1_000_000L,       // 1/1000s
        10_000_000L,      // 1/100s
        16_666_667L,      // 1/60s
        33_333_333L,      // 1/30s
        8_000_000_000L / 8, // ~1/8s
        100_000_000L,     // 0.1s
        250_000_000L,     // 0.25s
        500_000_000L,     // 0.5s
        1_000_000_000L,   // 1s
        2_500_000_000L,   // 2.5s
        8_000_000_000L    // 8s
    )
    for (ns in cases) {
        println("$ns -> ${formatShutterSpeed(ns)}")
    }
}

