spans = []  # (start, end, is_line_comment)
stack = ['code']
depths = []  # brace depth per 'tpl' context
i = 0
while i < n:
    c = src[i]
    nx = src[i+1] if i+1 < n else ''
    ctx = stack[-1]
    if ctx in ('code', 'tpl'):
        if c == '/' and nx == '/':
            j = i
            while j < n and src[j] != '\n':
                j += 1
            spans.append((i, j, True))
            i = j
            continue
        if c == '/' and nx == '*':
            j = i + 2
            while j < n - 1 and not (src[j] == '*' and src[j+1] == '/'):
                j += 1
            end = min(j + 2, n)
            spans.append((i, end, False))
            i = end
            continue
        if c == '"':
            if src[i:i+3] == '"""':
                stack.append('tstr'); i += 3; continue
            stack.append('str'); i += 1; continue
        if c == "'":
            stack.append('chr'); i += 1; continue
        if ctx == 'tpl':
            if c == '{':
                depths[-1] += 1
            elif c == '}':
                if depths[-1] == 1:
                    stack.pop(); depths.pop()
                else:
                    depths[-1] -= 1
        i += 1
        continue
    if ctx in ('str', 'tstr'):
        if c == '\\':
