        i += 1
        continue
    if ctx == 'chr':
        if c == '\\':
            i += 2
            continue
        if c == "'":
            stack.pop()
        i += 1
        continue

assert not [s for s in stack if s != 'code'], f"unbalanced contexts: {stack}"
spans.sort()
