    if is_line:
        line_start = src.rfind('\n', 0, s) + 1
        prefix = src[line_start:s]
        if prefix.strip() == '':
            # comment-only line: remove whole line including its newline
            end = e + 1 if e < n and src[e] == '\n' else e
            out[s and line_start:end] = [] if False else []
            del out[line_start:end]
            removed_line_comments += 1
        else:
            cut = s
            if cut > 0 and src[cut-1] in ' \t':
                cut -= 1
            del out[cut:e]
            trailing_removed += 1
    else:
        line_start = src.rfind('\n', 0, s) + 1
        prefix = src[line_start:s]
        if prefix.strip() == '' and (e >= n or src[e] == '\n' or src[e:].strip() == ''):
            end = e
            if e < n and src[e] == '\n':
                end += 1
            # if code follows on same line, don't eat it; only remove span (+preceding space)
            if src[e:].split('\n', 1)[0].strip():
                cut = s
                if cut > 0 and src[cut-1] in ' \t':
                    cut -= 1
                del out[cut:e]
                trailing_removed += 1
            else:
                del out[line_start:end]
                removed_line_comments += 1
        else:
            cut = s
            if cut > 0 and src[cut-1] in ' \t':
                cut -= 1
            del out[cut:e]
            trailing_removed += 1

result = ''.join(out)
open(path, 'w', encoding='utf-8').write(result)
print(f"removed {removed_line_comments} comment-only lines, {trailing_removed} trailing comments")
print(f"lines before: {src.count(chr(10))}, after: {result.count(chr(10))}")

