fun Context.findActivity(): ComponentActivity? = when (this) {
    is ComponentActivity -> this
    is ContextWrapper -> baseContext.findActivity()
    else -> null
}

private fun Context.registerVideoToggleReceiver() {
    (findActivity() as? MainActivity)?.let { activity ->
        ContextCompat.registerReceiver(
            this,
            activity.getRecordingReceiver(),
            IntentFilter(TOGGLE_VIDEO_ACTION),
            ContextCompat.RECEIVER_NOT_EXPORTED
        )
    }
}

private fun Context.unregisterVideoToggleReceiver() {
    (findActivity() as? MainActivity)?.let { activity ->
        try {
            unregisterReceiver(activity.getRecordingReceiver())
        } catch (e: Exception) {
        }
    }
}
